Object.assign(D.uk,{"svc.b.h1": "Брекети та елайнери в Одесі", "svc.b.photo": "Кабінет ортодонта", "svc.b.intro": "Рівні зуби й правильний прикус — це не лише красива усмішка, а й здоров'я зубів та суглобів. Ортодонт проведе діагностику, складе план лікування та підбере систему: брекети або елайнери."});Object.assign(D.en,{"svc.b.h1": "Braces and aligners in Odessa", "svc.b.photo": "Orthodontist's treatment room", "svc.b.intro": "Straight teeth and a correct bite are not only about a beautiful smile, but also about the health of your teeth and jaw joints. An orthodontist will run diagnostics, draw up a treatment plan and choose the right system: braces or aligners.", "pr.n.155": "Use of an orthodontic bracket system (partially self-ligating American Orthodontics Empower, USA (1 jaw))", "pr.n.156": "Use of an orthodontic bracket system (metal ligature-based Ormco Mini, USA)", "pr.n.157": "Use of an orthodontic bracket system (metal ligature-based American Orthodontics Mini Master, USA)", "pr.n.158": "Use of an orthodontic bracket system (metal self-ligating WBT, South Korea)", "pr.n.159": "Use of an orthodontic bracket system (metal self-ligating NB Mini IMD, South Korea)", "pr.n.160": "Use of an orthodontic bracket system (metal self-ligating American Orthodontics Empower, USA)", "pr.n.161": "Use of an orthodontic bracket system (esthetic self-ligating American Orthodontics Empower Clear, USA)", "pr.n.162": "Use of an orthodontic bracket system (self-ligating metal Damon Q, USA)", "pr.n.163": "Use of an orthodontic bracket system (self-ligating esthetic Damon Q Clear, USA)", "pr.n.164": "Use of an orthodontic bracket system (self-ligating metal Damon Ultima, USA)", "pr.n.165": "Use of an orthodontic bracket system (self-ligating esthetic Damon Ultima Clear, USA)", "pr.n.166": "Use of an orthodontic bracket system Insignia (USA)", "pr.n.188": "Teeth polishing after removal of braces (1 jaw)"});
Object.assign(D.uk,{"svc.b.photo": "Пацієнтка з брекетами", "svc.i.h1": "Імплантація зубів в Одесі", "svc.i.photo": "Лікар проводить імплантацію зуба", "svc.x.h1": "Видалення зуба в Одесі", "svc.x.photo": "Видалення зуба під час прийому"});Object.assign(D.en,{"svc.b.photo": "A smiling patient with braces", "svc.i.h1": "Dental implantation in Odessa", "svc.i.photo": "A dentist performing an implant procedure", "svc.x.h1": "Tooth extraction in Odessa", "svc.x.photo": "Tooth extraction in progress", "pr.n.263": "Surgical placement of a MegaGen ST implant", "pr.n.264": "Surgical placement of a Neodent implant", "pr.n.265": "Surgical placement of a MegaGen AnyRidge implant", "pr.n.266": "Surgical placement of a Straumann BLT/TL implant (SLA)", "pr.n.267": "Surgical placement of a Straumann BLT/TL implant (SLA activ)", "pr.n.268": "Surgical placement of a Straumann BLX/TLX/BLC/TLC implant (SLA)", "pr.n.269": "Surgical placement of a Straumann BLX/TLX/BLC/TLC implant (SLA active)", "pr.n.271": "Surgical placement of a Nobel Parallel implant", "pr.n.272": "Surgical placement of a Nobel Active implant", "pr.n.273": "Surgical placement of a Nobel Parallel TiUltra implant", "pr.n.274": "Surgical placement of a Nobel Active TiUltra implant", "pr.n.80": "Extraction of a primary tooth (physiological tooth replacement)", "pr.n.81": "Extraction of a primary tooth"});
Object.assign(D.uk,{"svc.h.crumb": "Гігієнічні та пародонтологічні послуги", "svc.h.h1": "Гігієна та пародонтологія", "svc.h.photo": "Лікарі проводять професійну гігієну пацієнтці", "svc.h.intro": "Професійна гігієна та пародонтологічні послуги важливі, щоб ваша усмішка залишалася красивою, подих — свіжим, а ротова порожнина — здоровою."});Object.assign(D.en,{"svc.h.crumb": "Hygienic and periodontic services", "svc.h.h1": "Hygiene and periodontology", "svc.h.photo": "Doctors performing professional hygiene on a patient", "svc.h.intro": "Professional hygiene and periodontal services are important to keep your smile beautiful, your breath fresh and your oral cavity healthy.", "pr.n.42": "Removal of soft dental deposits", "pr.n.47": "Remineralization therapy with Fluor Protect (2 jaws)", "pr.n.50": "Medication application to the oral mucosa", "pr.n.52": "Whitening of a discolored tooth (1 tooth)", "pr.n.56": "Device-assisted teeth whitening (Beyond Polus), 1 procedure", "pr.n.57": "Comprehensive professional teeth whitening", "pr.n.54": "Fabrication of a whitening tray", "pr.n.55": "Teeth whitening with Opalescence Boost", "pr.n.72": "Teeth whitening with the ART system (maintenance of results)", "pr.n.58": "Professional dental cleaning with Cavitron", "pr.n.59": "Instrument-assisted curettage with Cavitron (segment/quadrant)", "pr.n.62": "Instrument-assisted cleaning around implants with Cavitron (1 tooth)", "pr.n.63": "Bacterial culture testing", "pr.n.64": "Antibiotic susceptibility testing", "pr.n.65": "Bacteriophage susceptibility testing", "pr.n.66": "Periodontal case management", "pr.n.68": "Use of a tray with ULTRA EZ gel (desensitizer for relief of tooth sensitivity)", "pr.n.69": "Injectable gingival restoration with Hyadent BG (1 area)", "pr.n.70": "Injectable gingival restoration with Hyadent BG (full course)", "pr.n.73": "Ongoing dental hygiene care"});
Object.assign(D.uk,{"dd.ceramista": "Лабораторія Ceramista", "cer.h1": "Ceramista — зуботехнічна лабораторія", "cer.photo": "Зубний технік працює з гіпсовою моделлю щелепи", "cer.p": "Лабораторія оснащена інструментами DENTSPLY SIRONA. Керамічні коронки та вініри дають змогу повернути пацієнтові усмішку й покращити функціональність зубів. Наші зубні техніки виготовляють коронки, вініри та інші конструкції індивідуально для кожного пацієнта. Завдяки цьому пацієнти повертають собі зуби з їхньою формою та функцією й правильним прикусом, який ніхто не помічає. Зубні техніки працюють у команді з лікарем і пацієнтом, а це підвищує ефективність роботи.", "cer.ah": "Про <span class=\"blue\">Ceramista</span>", "cer.ap": "Головна перевага керамічних протезів — вони зовсім непомітні й не впадають в око: це стовідсоткова імітація вашого власного зуба! Так лікарі відновлюють не лише форму та функцію зуба, а й його красивий вигляд."});Object.assign(D.en,{"dd.ceramista": "Ceramista laboratory", "cer.h1": "Ceramista – dental laboratory", "cer.photo": "A dental technician working with a plaster jaw model", "cer.p": "The laboratory is equipped with DENTSPLY SIRONA instruments. Ceramic crowns and veneers make it possible to restore a patient's smile and improve the function of the teeth. Our dental technicians make crowns, veneers and other restorations individually for every patient. As a result, patients get their teeth back with natural shape and function and a correct bite that no one notices. Dental technicians work in a team with the dentist and the patient, which increases the efficiency of the work.", "cer.ah": "About <span class=\"blue\">Ceramista</span>", "cer.ap": "The key advantage of ceramic prostheses is that they are completely imperceptible and invisible to the eye: a 100% imitation of your own tooth! This way dentists restore not only the shape and function of the tooth, but also its beautiful appearance."});
Object.assign(D.uk,{"svc.c.h1": "Лікування карієсу в Одесі", "svc.c.photo": "Лікар із бінокулярною лупою лікує зуб пацієнтці", "svc.k.h1": "Дитяча стоматологія в Одесі", "svc.k.photo": "Маленький пацієнт на прийомі в дитячого стоматолога", "svc.k.intro": "Наші лікарі завжди потоваришують із маленькими пацієнтами! Регулярні огляди та лікування для всіх членів родини в одному місці! Щотижневі Kinder Party дуже популярні серед дітей."});Object.assign(D.en,{"svc.c.h1": "Caries treatment in Odessa", "svc.c.photo": "A dentist with loupes treating a patient's tooth", "svc.k.h1": "Pediatric dentistry in Odessa", "svc.k.photo": "A young patient at the pediatric dentist", "svc.k.intro": "Our dentists always make friends with little patients! Regular check-ups and treatment for all family members in one place! The weekly Kinder Party is very popular among children.", "pr.n.74": "Adaptation visit", "pr.n.75": "Pediatric dentist consultation", "pr.n.76": "Local anesthesia/electronically controlled anesthesia (1 tooth), Septanest 1/100000", "pr.n.77": "Treatment of pulpitis in a primary tooth", "pr.n.78": "Treatment of apical periodontitis in a primary tooth", "pr.n.79": "Localized MTA capping", "pr.n.82": "Placement of a pediatric metal crown", "pr.n.83": "Pediatric metal crown for a permanent tooth", "pr.n.84": "Pediatric Biofix Crown", "pr.n.85": "Placement of a pediatric crown (esthetic)", "pr.n.86": "Remineralization therapy using trays (2 jaws)", "pr.n.87": "Fissure sealing of a primary tooth", "pr.n.88": "Fissure sealing of a permanent tooth", "pr.n.89": "Restoration of a primary tooth, complexity level 1", "pr.n.90": "Restoration of a primary tooth, complexity level 2", "pr.n.91": "Restoration of a primary tooth, complexity level 3", "pr.n.92": "Professional dental cleaning for primary dentition", "pr.n.93": "Professional dental cleaning for mixed dentition"});
Object.assign(D.uk,{"dd.kinder": "Kinder Party", "svc.v.h1": "Вініри в Одесі", "svc.v.photo": "Усмішка до та після встановлення вінірів", "svc.v.p1": "Вініри — це сучасний метод реставрації зубів, який дозволяє повернути не лише функціональність зубів, а й їхній естетичний вигляд. Метод полягає у використанні тонких керамічних шарів, які накладаються на передню поверхню зуба. Це дає змогу відновити його форму, колір і розмір, зберігаючи природний вигляд. Відгуки пацієнтів нашої стоматології свідчать, що естетика зубів має для них велике значення. Наші спеціалісти виготовляють керамічні вініри, які виглядають дуже природно: кераміка відображає світло так само, як і натуральні зуби.", "svc.v.p2": "Крім того, вініри можуть вирішувати різні проблеми із зубами, такі як відсутність частини зуба, незадовільна форма або колір. У нашій стоматології ми використовуємо різні види вінірів залежно від індивідуальних потреб пацієнта. Зокрема, пропонуємо безпечні та надійні вініри, які відображають світло з природною градацією кольорів, а також вініри з ліцензованої кераміки E-MAX, що має високу міцність і довговічність. Ми використовуємо сучасне обладнання та передові технології, щоб забезпечити максимальну точність і надійність при виготовленні вінірів. Завдяки вінірам ви можете відновити свою посмішку й знову почуватися впевнено! Не зволікайте і зробіть перший крок до ідеальної посмішки. Записуйтеся на консультацію до наших спеціалістів та дізнайтеся більше про можливості вінірів.", "kd.p": "Наші лікарі з увагою ставляться до кожного маленького пацієнта, діагностують і призначають лікування з особливою турботою. Якби Зубна фея передавала молочні зубчики найтурботливішим лікарям, вона неодмінно залишила б їх у нашій клініці.", "kd.btn": "Записатися", "kd.c1": "Дитяче свято в стоматології? Так, це можливо! Нам особливо важливо допомогти і дорослим, і маленьким пацієнтам, створивши приємну атмосферу та веселе свято просто в стоматології.", "kd.c2": "Dental Center відвідують діти різного віку, і ми з радістю знаходимо особливий підхід до кожного з них.", "kd.free": "Абсолютно безкоштовно", "kd.gal": "Фото Kinder Party", "a.kgprev": "Попереднє фото", "a.kgnext": "Наступне фото", "kd.a1": "Хлопчик із помаранчевим захисним екраном", "kd.a2": "Лікарка показує догляд за зубами на іграшковій моделі", "kd.a3": "Дві дівчинки в помаранчевих окулярах показують знак перемоги", "kd.a4": "Дівчинка в масці з дзеркальцем і інструментом", "kd.a5": "Хлопчик показує диплом «За сміливість і усмішку»", "kd.a6": "Діти з піднятими руками в жовтих, синіх і помаранчевих рукавичках", "kd.a7": "Дівчинка лікує зуби плюшевому ведмедику", "kd.a8": "Хлопчик у масці та жовтих рукавичках махає рукою", "kd.a9": "Усміхнена дівчинка в навушниках і рожевих окулярах у кріслі"});Object.assign(D.en,{"dd.kinder": "Kinder Party", "svc.v.h1": "Veneers in Odessa", "svc.v.photo": "A smile before and after veneers", "svc.v.p1": "Veneers are a modern method of tooth restoration that lets you regain not only the function of your teeth, but also their esthetic appearance. The method uses thin ceramic layers applied to the front surface of the tooth. This restores its shape, color and size while keeping a natural look. Feedback from our patients shows that the esthetics of teeth matters a great deal to them. Our specialists make ceramic veneers that look very natural: ceramic reflects light in the same way natural teeth do.", "svc.v.p2": "In addition, veneers can solve a range of dental problems, such as a missing part of a tooth or an unsatisfactory shape or color. At our clinic we use different types of veneers depending on the individual needs of the patient. In particular, we offer safe and reliable veneers that reflect light with a natural gradation of shades, as well as veneers made of licensed E-MAX ceramic, which is highly strong and durable. We use modern equipment and advanced technology to ensure maximum precision and reliability in making veneers. Thanks to veneers you can restore your smile and feel confident again! Don't put it off and take the first step towards a perfect smile. Sign up for a consultation with our specialists and learn more about what veneers can do.", "kd.p": "Our dentists treat every little patient with attention, make the diagnosis and prescribe treatment with special care. If the Tooth Fairy passed baby teeth to the most caring dentists, she would definitely leave them at our clinic.", "kd.btn": "Sign up", "kd.c1": "Children's holidays in dentistry? Yes, it is possible! It is especially important for us to help both adults and young patients by creating a pleasant atmosphere and a fun holiday right in the dental clinic.", "kd.c2": "Dental Center is visited by children of all ages, and we are happy to find a special approach to each of them.", "kd.free": "Absolutely free", "kd.gal": "Kinder Party photos", "a.kgprev": "Previous photo", "a.kgnext": "Next photo", "kd.a1": "A boy holding an orange protective shield", "kd.a2": "A doctor showing dental care on a toy model", "kd.a3": "Two girls in orange goggles making peace signs", "kd.a4": "A girl in a mask with a dental mirror and a tool", "kd.a5": "A boy showing a «For courage and a smile» diploma", "kd.a6": "Children with raised hands in yellow, blue and orange gloves", "kd.a7": "A girl treating the teeth of a teddy bear", "kd.a8": "A boy in a mask and yellow gloves waving", "kd.a9": "A smiling girl in headphones and pink glasses in the dental chair", "pr.n.96": "Fabrication and placement of a temporary crown (direct method)", "pr.n.97": "Fabrication and placement of a PMMA veneer/crown", "pr.n.98": "Fabrication and placement of a zirconia crown (basic)", "pr.n.99": "Fabrication and placement of a zirconia crown (monochrome)", "pr.n.100": "Fabrication and placement of a zirconia crown (Multilayer)", "pr.n.101": "Fabrication and placement of a zirconia crown (with micro-layering of ceramics)", "pr.n.102": "Fabrication and placement of a zirconia crown (individual esthetic design)", "pr.n.103": "Fabrication and placement of a zirconia crown/veneer (custom work by Joshua Polansky, USA)", "pr.n.104": "Fabrication and placement of a ceramic restoration (CEREC)", "pr.n.105": "Fabrication and placement of a ceramic restoration (CEREC, artistic execution)", "pr.n.106": "Fabrication and placement of a ceramic restoration (Emotions)", "pr.n.107": "Fabrication and placement of a ceramic restoration (E-MAX)", "pr.n.108": "Fabrication and placement of a ceramic restoration (E-MAX, anatomical micro-layering)", "pr.n.109": "Fabrication and placement of a ceramic restoration (fabricated on a refractory die)", "pr.n.118": "Removal of an existing veneer/crown", "pr.n.119": "Recementation of an existing veneer/crown"});
Object.assign(D.uk,{"dm.h1": "DentalMobile — стоматолог додому в Одесі", "dm.lead": "Зубний біль буває нестерпним! У таких випадках на допомогу приходить DentalMobile — можливість викликати стоматолога додому. Лікар приїде, проведе огляд і навіть може розпочати лікування, або терміново відвезе вас до клініки й надасть допомогу.", "dm.alt": "Автомобіль DentalMobile біля клініки Dental Center", "dm.c1": "<b>15 хв</b> — у центрі міста", "dm.c2": "<b>30 хв</b> — за межами міста", "dm.ah": "<span class=\"blue\">DentalMobile</span>", "dm.ap": "Ми перші в Одесі, хто дбає про здоров'я ваших зубів у вас вдома. Після дзвінка до вас на адресу їде команда стоматологів. Не бійтеся зубного болю — DentalMobile завжди прийде на допомогу!", "dm.s1h": "Виїзна стоматологія в Одесі", "dm.s1p1": "Кожен одесит хоча б раз звертався до послуг стоматолога в плановому чи терміновому порядку. Сьогодні лікарі-стоматологи допомагають вирішити ряд проблем, пов'язаних із захворюваннями ротової порожнини. Але бувають такі випадки, коли потрібен виклик стоматолога додому в Одесі. Наприклад, до людини похилого віку, яка не може самостійно пересуватися, а у вас немає можливості транспортувати її. Або до лежачого хворого, який навіть за допомогою рідних не може покинути межі житла.", "dm.s1p2": "Індивідуальний виклик стоматолога додому в Одесі або до будинку престарілих — це оптимальне рішення для надання допомоги пенсіонерам та людям з обмеженими можливостями.", "dm.s1p3": "Лікарі-стоматологи клініки Dental Center готові виїхати вам на допомогу у зручний час.", "dm.s2h": "Виїзд зубного лікаря додому в Одесі від <span class=\"blue\">Dental Center</span>", "dm.s2p": "Наші лікарі знаходять індивідуальний підхід до людей похилого віку та людей з обмеженими можливостями. Наше завдання — надати швидку, якісну та ефективну допомогу:", "dm.st1": "Вирішуємо широкий спектр проблем, пов'язаних зі здоров'ям ротової порожнини: ставимо пломби, видаляємо пошкоджені або зруйновані зуби, проводимо лікування запалень і флюсу, протезування, допомагаємо при травмуванні ротової порожнини.", "dm.st2": "Працюємо у будні та вихідні дні. Приїжджаємо на термінові виклики та надаємо допомогу.", "dm.st3": "Проводимо повне обстеження ротової порожнини та оцінку стану зубів, погоджуємо план лікування з пацієнтом або його опікуном, далі проводимо ефективне лікування та знімаємо біль.", "dm.s3h": "Наші переваги", "dm.ad1": "У нашому розпорядженні є передове мобільне стоматологічне обладнання, розроблене спеціально для надання допомоги вдома. Воно дозволяє провести всі необхідні процедури вдома. Бормашина, слиновідсмоктувач, стоматологічне крісло — бригада повністю оснащена всім необхідним.", "dm.ad2": "Ми закуповуємо обладнання, яке відповідає вимогам міжнародних стандартів якості, безпечне для здоров'я лікаря та пацієнта.", "dm.ad3": "Працюємо з якісним, міцним та надійним матеріалом.", "dm.ad4": "У наших стоматологів завжди при собі є інструменти та знеболювальні препарати, які допоможуть зняти зубний біль і запалення, пролікувати або вирвати зуб.", "dm.end": "Замовляйте стоматологію з виїздом в Одесі на нашому сайті. Просто заповніть форму зворотного зв'язку або зв'яжіться з адміністратором нашої клініки. Ми підберемо оптимальний час для прибуття стоматолога додому в Одесі та запропонуємо максимально комфортні ціни на весь перелік послуг.", "dm.more": "Докладніше про DentalMobile"});Object.assign(D.en,{"dm.h1": "DentalMobile — a dentist at home in Odessa", "dm.lead": "Toothache can be unbearable! In such cases DentalMobile comes to the rescue — your chance to call a dentist to your home. The doctor will come, examine you and may even begin treatment, or urgently take you to the clinic and provide care.", "dm.alt": "The DentalMobile van outside the Dental Center clinic", "dm.c1": "<b>15 min</b> — in the city center", "dm.c2": "<b>30 min</b> — outside the city", "dm.ah": "<span class=\"blue\">DentalMobile</span>", "dm.ap": "We are the first in Odessa to care about the health of your teeth right at your place. After we receive a call, a team of dentists comes to your address. Don't be afraid of dental pain — DentalMobile is always there to help!", "dm.s1h": "Mobile dentistry in Odessa", "dm.s1p1": "Every resident of Odessa has turned to a dentist at least once, for a planned or an urgent visit. Today dentists help solve a range of problems related to oral diseases. But there are cases when a dentist's home visit in Odessa is needed. For example, for an elderly person who cannot move around on their own, when you have no way of transporting them. Or for a bedridden patient who cannot leave the home even with the help of relatives.", "dm.s1p2": "A personal dentist's call-out to your home in Odessa or to a nursing home is the best way to provide care to pensioners and people with limited mobility.", "dm.s1p3": "The dentists of the Dental Center clinic are ready to come to your aid at a convenient time.", "dm.s2h": "A dentist's home visit in Odessa from <span class=\"blue\">Dental Center</span>", "dm.s2p": "Our doctors find an individual approach to elderly people and people with limited mobility. Our task is to provide fast, high-quality and effective care:", "dm.st1": "We solve a wide range of oral health problems: we place fillings, remove damaged or destroyed teeth, treat inflammation and gumboils, fit prostheses and help with oral injuries.", "dm.st2": "We work on weekdays and weekends. We come to urgent calls and provide help.", "dm.st3": "We carry out a full oral examination and assess the condition of the teeth, agree the treatment plan with the patient or their guardian, then provide effective treatment and relieve pain.", "dm.s3h": "Our advantages", "dm.ad1": "We have advanced mobile dental equipment designed specially for providing care at home. It allows all the necessary procedures to be carried out at home. A drill, a saliva ejector, a dental chair — the team is fully equipped with everything it needs.", "dm.ad2": "We purchase equipment that meets international quality standards and is safe for the health of both doctor and patient.", "dm.ad3": "We work with high-quality, strong and reliable materials.", "dm.ad4": "Our dentists always carry instruments and anaesthetics that help relieve toothache and inflammation, treat or remove a tooth.", "dm.end": "Order a dentist's home visit in Odessa on our website. Just fill in the feedback form or contact our clinic's administrator. We will choose the best time for the dentist to arrive at your home in Odessa and offer the most comfortable prices for the whole list of services.", "dm.more": "More about DentalMobile"});
Object.assign(D.uk,{"nar.crumb": "Стоматологія уві сні", "nar.h1": "Лікування зубів в Одесі", "nar.photo": "Команда лікарів проводить лікування пацієнтці під наркозом", "nar.intro": "Загальна анестезія або седація дозволяє пацієнту проспати всю стоматологічну процедуру. Ви не відчуватимете ні вигляду, ні запахів, ні звуків, а отже — ні страху, тривоги та дискомфорту. Лікування уві сні стало стандартом у багатьох клініках світу. Більше того, воно обов'язкове для пацієнтів з особливими потребами: ДЦП, аутизм, неврологічні захворювання, або якщо в пацієнта алергія на місцеву анестезію."});Object.assign(D.en,{"nar.crumb": "Sleep dentistry", "nar.h1": "Dental treatment in Odessa", "nar.photo": "A team of doctors treating a patient under anaesthesia", "nar.intro": "General anaesthetic or sedation patients sleep through the entire dental procedure. You will be unaware of the sight, smell and sounds, easing fear, anxiety and discomfort. Sleep dentistry became standard in many dental clinics around the world. Moreover, sleep through is a must for patients with special needs: cerebral palsy, autism, neurological diseases or if a patient is allergic to local anesthesia."});
Object.assign(D.uk,{"or.h1": "Ортодонтія в Одесі", "or.photo": "Лікар-ортодонт проводить огляд пацієнтки", "or.intro": "Консультація лікаря-ортодонта — перший крок до ідеальної усмішки! Не вагайтеся почати лікування неправильного прикусу — і ви отримаєте усмішку своєї мрії!", "su.h1": "Хірургічна стоматологія в Одесі", "su.photo": "Хірург проводить втручання в ротовій порожнині пацієнтки", "su.intro": "Хірургічна стоматологія — це не лише видалення зубів, а й безліч інших процедур, які допомагають зберегти зуби та створити належні умови для функціонування зубощелепної системи."});Object.assign(D.en,{"or.h1": "Orthodontics in Odessa", "or.photo": "An orthodontist examining a patient", "or.intro": "The orthodontist's consultation is the first step to a perfect smile! Don't hesitate to start treating your malocclusion and you will get the smile you are dreaming of!", "su.h1": "Dental surgery in Odessa", "su.photo": "A surgeon performing a procedure in a patient's mouth", "su.intro": "Oral surgery means not only tooth extraction, but also many other procedures that help keep your teeth and create proper conditions for the functioning of the dentoalveolar system."});
Object.assign(D.uk,{"mi.crumb": "Мікроскоп Leica", "mi.h1": "Лікування під мікроскопом Leica", "mi.photo": "Лікар працює за стоматологічним мікроскопом Leica", "mi.intro": "Мікроскопи від світового лідера допомагають нашим лікарям помітити найменший дефект чи деформацію ваших зубів. Компанія LEICA відома у світі понад 150 років. Стоматологічний мікроскоп Leica забезпечує стабільно високу якість роботи завдяки найкращій оптиці, високому збільшенню та яскравому денному освітленню.", "di.photo": "Лікар розглядає КТ-знімки щелеп на моніторі"});Object.assign(D.en,{"mi.crumb": "Leica microscope", "mi.h1": "Treatment under the Leica microscope", "mi.photo": "A dentist working with a Leica dental microscope", "mi.intro": "Microscopes from the world leader help our dentists notice the smallest defect or deformation of your teeth. LEICA has been known worldwide for more than 150 years. The Leica dental microscope ensures consistently high-quality work thanks to the best optics, high magnification and bright daylight illumination.", "di.photo": "A doctor studying CT scans of the jaws on a monitor"});
Object.assign(D.uk,{"op.h1": "Лікар-ортопед в Одесі", "op.photo": "Лікарі проводять цифрове сканування зубів пацієнтці", "op.intro": "Ортопедичне лікування вирішує як естетичні, так і функціональні проблеми. Наші лікарі відновлять ваші зуби так, щоб вони виглядали максимально природно, а ви могли усміхатися, сміятися й почуватися комфортно в будь-якій ситуації!"});Object.assign(D.en,{"op.h1": "Orthopedic dentist in Odessa", "op.photo": "Doctors performing a digital dental scan on a patient", "op.intro": "Restorative dental procedures can solve both cosmetic and functional problems. Our dentists will restore your teeth to look as natural as possible, so you can smile, laugh and feel comfortable in any situation!"});
