/* Lead form: the name accepts letters only; the phone is a digits-only +38 (0__) ___-__-__ mask */
(function(){
var nm=document.getElementById('leadName'),ph=document.getElementById('leadPhone');
if(!nm||!ph)return;
function en(){return document.documentElement.lang==='en';}
/* --- name: letters (any alphabet) and single spaces only --- */
nm.addEventListener('input',function(){
  var old=nm.value,pos=nm.selectionStart,v=old.replace(/[^\p{L} ]/gu,'').replace(/^ +/,'').replace(/ {2,}/g,' ');
  if(v!==old){nm.value=v;var p=Math.max(0,Math.min(v.length,pos-(old.length-v.length)));try{nm.setSelectionRange(p,p);}catch(e){}}
  nm.setCustomValidity(v.trim()?'':(en()?'Enter your name':'Введіть ім\'я'));
});
/* --- phone --- */
function digitsOf(raw){
  var d=raw.replace(/\D/g,'');
  if(d.indexOf('380')===0)d=d.slice(3);else if(d.indexOf('38')===0)d=d.slice(2);
  if(d.charAt(0)==='0')d=d.slice(1);
  return d.slice(0,9);
}
function fmt(d){
  function g(a,b){var x=d.slice(a,b);while(x.length<b-a)x+='_';return x;}
  return '+38 (0'+g(0,2)+') '+g(2,5)+'-'+g(5,7)+'-'+g(7,9);
}
function render(d){
  ph.value=fmt(d);
  var i=ph.value.indexOf('_');if(i<0)i=ph.value.length;
  try{ph.setSelectionRange(i,i);}catch(e){}
  ph.setCustomValidity(d.length===9?'':(en()?'Enter the full phone number':'Введіть повний номер телефону'));
}
function cur(){return ph.value?digitsOf(ph.value):'';}
ph.addEventListener('focus',function(){render(cur());});
ph.addEventListener('click',function(){render(cur());});
ph.addEventListener('input',function(){render(digitsOf(ph.value));});
ph.addEventListener('keydown',function(e){
  if(e.key==='Backspace'||e.key==='Delete'){e.preventDefault();var sel=ph.selectionEnd-ph.selectionStart;render(sel>0?'':cur().slice(0,-1));}
});
ph.addEventListener('blur',function(){if(!cur()){ph.value='';ph.setCustomValidity('');}});
if(ph.form)ph.form.addEventListener('reset',function(){setTimeout(function(){ph.value='';ph.setCustomValidity('');nm.setCustomValidity('');},0);});
})();
